const body = $input.first().json.body || $input.first().json;
const payload = body.payload || body;
const from = payload.from || payload.chatId || body.from || '';
const messageText = (payload.body || payload.text || '').trim();
const sessionName = body.session || 'default';
const isFromMe = payload.fromMe || false;
const isGroup = from.includes('@g.us');
if (isFromMe || isGroup) return [{ json: { skip: true } }];
const cleanPhone = from.replace('@c.us', '').replace('@s.whatsapp.net', '');
const msgLower = messageText.toLowerCase().trim();
const isReactivation = ['#bot', '/bot', '#ativar', '/ativar'].includes(msgLower);
const greetingRegex = /^(oi|ol[aá]|boa tarde|bom dia|boa noite|hey|hello|tudo bem|tudo bom|e a[ií]|oie|oii)[\s!?.]*$/i;
const isGreeting = greetingRegex.test(messageText.trim());
const criticalRegex = /(atendente|humano|pessoa|rescis[aã]o|procon|jur[ií]dico|advogado|processo|justi[çc]a|reclama[çc][aã]o|cancelar|distrato|falar com algu[eé]m|quero falar)/i;
const isCritical = criticalRegex.test(messageText);
return [{ json: { skip: false, from, phone: cleanPhone, message: messageText, session: sessionName, isReactivation, isGreeting, isCritical, timestamp: new Date().toISOString() } }];

// CORRIGIDO: Estado agora salvo no Qdrant (persistente entre reinicializações)
// Por simplicidade no n8n, mantemos o staticData apenas para flag de handoff
// O histórico real fica salvo na collection 'longview_historico' no Qdrant
const from = $input.first().json.from;
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
if (staticData.humanHandoff[from]) delete staticData.humanHandoff[from];

return [{ json: { to: from, session: $input.first().json.session, responseText: '✅ Olá! Estou de volta para te ajudar com informações sobre os empreendimentos LongView. Como posso te auxiliar?' } }];

const from = $input.first().json.from;
const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const handoffEntry = staticData.humanHandoff[from];
let isInHumanMode = false;
if (handoffEntry) {
  const elapsed = Date.now() - new Date(handoffEntry.since).getTime();
  if (elapsed < 8 * 60 * 60 * 1000) {
    isInHumanMode = true;
  } else {
    delete staticData.humanHandoff[from];
  }
}
return [{ json: { ...$input.first().json, isInHumanMode } }];

const qdrantResult = $input.first().json;
const results = qdrantResult.result || [];
const prevNode = $('Verificar Estado').first().json;
const MIN_SCORE = 0.72;
const validResults = results.filter(r => r.score >= MIN_SCORE);
const hasContext = validResults.length > 0;
const topScore = results.length > 0 ? results[0].score : 0;
const contextText = validResults
  .map(r => `Documento: ${r.payload?.source || 'Material LongView'}\nTrecho: ${r.payload?.text || r.payload?.pageContent || ''}\n(Relevância: ${(r.score * 100).toFixed(0)}%)`)
  .join('\n\n---\n\n');
return [{ json: { ...prevNode, hasContext, contextText, shouldHandoff: !hasContext, topScore, handoffReason: !hasContext ? 'sem_contexto_suficiente' : null } }];

