// CONFIGURAÇÃO: edite o número do atendente
const ATTENDANT_PHONE = 'SEU_NUMERO_AQUI@c.us'; // ex: 5548999990000@c.us

const from = $('Verificar Estado').first().json.from;
const session = $('Verificar Estado').first().json.session;
const question = $('Verificar Estado').first().json.message;
const isCritical = $('Verificar Estado').first().json.isCritical || false;
const topScore = $input.first().json.topScore || 0;
const handoffReason = isCritical ? 'assunto_critico' : ($input.first().json.handoffReason || 'sem_contexto');

const staticData = $getWorkflowStaticData('global');
if (!staticData.humanHandoff) staticData.humanHandoff = {};
const alreadyInHandoff = !!staticData.humanHandoff[from];
staticData.humanHandoff[from] = { since: new Date().toISOString(), reason: handoffReason };

const reasonLabel = {
  assunto_critico: '🔴 Assunto crítico (jurídico/rescisão/procon)',
  sem_contexto_suficiente: '🟡 Fora da base de conhecimento',
  sem_contexto: '🟡 Fora da base de conhecimento'
}[handoffReason] || '🟡 Motivo não identificado';

const attendantMsg = alreadyInHandoff
  ? `📩 *Nova mensagem — cliente em atendimento*\n\n*Cliente:* ${from.replace('@c.us','')}\n*Mensagem:* "${question}"`
  : `🔔 *Novo Transbordo — LongView*\n\n*Cliente:* ${from.replace('@c.us','')}\n*Última mensagem:* "${question}"\n*Motivo:* ${reasonLabel}\n*Score RAG:* ${(topScore*100).toFixed(0)}%\n*Horário:* ${new Date().toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}\n\nPara reativar a IA após atender, envie *#bot*.`;

return [{ json: {
  from, session,
  clientMessage: alreadyInHandoff ? null : 'Compreendo perfeitamente. Estou transferindo você agora para um dos nossos especialistas LongView para garantir o melhor atendimento. Em breve entraremos em contato! 🏢',
  attendantMessage: attendantMsg,
  attendantPhone: ATTENDANT_PHONE,
  handoffReason, topScore, alreadyInHandoff
} }];

// CORRIGIDO: Extrai resposta e prepara payload completo para log de histórico
const geminiResponse = $input.first().json;
const stateNode = $('Verificar Estado').first().json;
let responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || 'Desculpe, ocorreu um erro ao processar sua mensagem. Um de nossos especialistas entrará em contato.';

// Limpa possíveis artefatos do Gemini
responseText = responseText.trim();

return [{
  json: {
    to: stateNode.from,
    phone: stateNode.phone,
    session: stateNode.session,
    responseText: responseText,
    originalMessage: stateNode.message,
    timestamp: stateNode.timestamp || new Date().toISOString(),
    topScore: $('Validação de Confiança').first().json.topScore || 0,
    contextText: $('Validação de Confiança').first().json.contextText || ''
  }
}];

// NOVO NÓ: Salva o histórico completo da conversa no Qdrant
// Collection: longview_historico
// Cada registro contém: telefone, pergunta, resposta, score, contexto usado, timestamp
//
// IMPORTANTE: Você precisa criar a collection antes com:
// curl -X PUT http://localhost:6333/collections/longview_historico \
//   -H 'Content-Type: application/json' \
//   -d '{"vectors": {"size": 1, "distance": "Cosine"}}'
// (Usamos vetor dummy [0] pois não precisamos de busca semântica no histórico)

const data = $input.first().json;
const phone = data.phone || data.to?.replace('@c.us','') || 'desconhecido';
const timestamp = data.timestamp || new Date().toISOString();
const pointId = Date.now(); // ID único baseado em timestamp

const payload = {
  points: [{
    id: pointId,
    vector: [0], // vetor dummy — histórico não precisa de busca vetorial
    payload: {
      tipo: 'conversa_ia',
      telefone: phone,
      sessao: data.session || 'default',
      pergunta_cliente: data.originalMessage || '',
      resposta_ia: data.responseText || '',
      contexto_usado: data.contextText || '',
      score_relevancia: data.topScore || 0,
      timestamp: timestamp,
      data_hora_br: new Date(timestamp).toLocaleString('pt-BR', {timeZone: 'America/Sao_Paulo'})
    }
  }]
};

return [{ json: { payload: payload, phone: phone, timestamp: timestamp } }];

// NOVO NÓ: Salva transbordo no histórico também
// Registra transbordos para controle e análise posterior
const from = $('Preparar Transbordo').first().json.from;
const phone = from.replace('@c.us','').replace('@s.whatsapp.net','');
const stateNode = $('Verificar Estado').first().json;
const transbordoData = $('Preparar Transbordo').first().json;
const timestamp = new Date().toISOString();
const pointId = Date.now();

const payload = {
  points: [{
    id: pointId,
    vector: [0],
    payload: {
      tipo: 'transbordo',
      telefone: phone,
      sessao: stateNode.session || 'default',
      pergunta_cliente: stateNode.message || '',
      resposta_ia: '[TRANSBORDO — Atendimento humano ativado]',
      motivo_transbordo: transbordoData.handoffReason || 'desconhecido',
      score_relevancia: transbordoData.topScore || 0,
      timestamp: timestamp,
      data_hora_br: new Date(timestamp).toLocaleString('pt-BR', {timeZone: 'America/Sao_Paulo'})
    }
  }]
};

return [{ json: { payload: payload } }];

// NOVO NÓ: Injeta metadados do arquivo no binário antes de enviar ao Qdrant
// Isso garante que o campo 'source' no Qdrant tenha o nome real do PDF
const binaryData = $input.first().binary;
const binaryKey = Object.keys(binaryData || {})[0] || 'Documento (PDF)';
const fileName = binaryData?.[binaryKey]?.fileName || binaryData?.[binaryKey]?.name || 'documento-longview.pdf';
const fileNameClean = fileName.replace(/\.pdf$/i, '');

// Passa os metadados adiante junto com o binário
return [{
  json: {
    source: fileNameClean,
    fileName: fileName,
    uploadedAt: new Date().toISOString()
  },
  binary: binaryData
}];

const from = $input.first().json.from;
const session = $input.first().json.session;
const hour = new Date().getHours();
const greetings = [
  'Bom dia! Bem-vindo à LongView 🏢

Sou o assistente virtual e estou aqui para te ajudar com informações sobre nossos empreendimentos de alto padrão.

Como posso te auxiliar?',
  'Boa tarde! Bem-vindo à LongView 🏢

Sou o assistente virtual e estou aqui para te ajudar com informações sobre nossos empreendimentos de alto padrão.

Como posso te auxiliar?',
  'Boa noite! Bem-vindo à LongView 🏢

Sou o assistente virtual e estou aqui para te ajudar com informações sobre nossos empreendimentos de alto padrão.

Como posso te auxiliar?'
];
const idx = hour < 12 ? 0 : hour < 18 ? 1 : 2;
return [{ json: { to: from, session, responseText: greetings[idx] } }];
